'use client';
import { useEffect } from 'react';

// PANEL LEKTORA na gry.easygo-english.pl — ta sama domena co logowanie/konto/katalog,
// więc sesja Supabase (localStorage) jest widoczna. Cała logika przeniesiona 1:1
// z panel-lektora.html; zmienione tylko przekierowania na gry.easygo.
// HTML/CSS/JS zakodowane w base64, żeby backticki i ${} w oryginale nie psuły składni.

const CSS_B64 = "";
const BODY_B64 = "";
const SCRIPT_B64 = "";

function b64decode(s){
  if (typeof window === 'undefined') return '';
  return decodeURIComponent(escape(window.atob(s)));
}

export default function PanelLektora() {
  useEffect(() => {
    // dark mode od razu (bez mignięcia)
    try{ if(localStorage.getItem('easygo_tryb')==='dark'){ document.documentElement.classList.add('eg-dark'); } }catch(e){}

    // wstrzyknij CSS
    var css = b64decode(CSS_B64);
    var styleEl = document.createElement('style');
    styleEl.id = 'panel-lektora-css';
    styleEl.textContent = css;
    document.head.appendChild(styleEl);

    // wstrzyknij HTML do kontenera
    var mount = document.getElementById('panel-lektora-mount');
    if(mount){ mount.innerHTML = b64decode(BODY_B64); }

    // uruchom główny skrypt panelu (po załadowaniu Supabase)
    function runPanel(){
      var code = b64decode(SCRIPT_B64);
      var s = document.createElement('script');
      s.textContent = code;
      document.body.appendChild(s);
    }
    if(window.supabase){ runPanel(); }
    else {
      var sc = document.createElement('script');
      sc.src = 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';
      sc.onload = runPanel;
      document.head.appendChild(sc);
    }

    // sprzątanie przy odmontowaniu (gdyby Next przełączył stronę)
    return function(){
      var s1 = document.getElementById('panel-lektora-css');
      if(s1) s1.remove();
    };
  }, []);

  return <div id="panel-lektora-mount" />;
}
